// Bit’s Console Quest: Controller Foundry.

// ART (generated by art.py: do not edit)
const ART = {
  tiles: {"deckSide": 2, "deckTop": 1},
  sprites: {"heroBlink": {"pal": 0, "size": 32, "tile": 260}, "heroCheer": {"pal": 0, "size": 32, "tile": 392}, "heroFall": {"pal": 0, "size": 32, "tile": 332}, "heroIdle": {"pal": 0, "size": 32, "tile": 256}, "heroJump": {"pal": 0, "size": 32, "tile": 328}, "heroLand": {"pal": 0, "size": 32, "tile": 388}, "heroPlug": {"pal": 0, "size": 32, "tile": 384}, "heroWalk1": {"pal": 0, "size": 32, "tile": 264}, "heroWalk2": {"pal": 0, "size": 32, "tile": 268}, "heroWalk3": {"pal": 0, "size": 32, "tile": 320}, "heroWalk4": {"pal": 0, "size": 32, "tile": 324}, "labConsole": {"pal": 3, "size": 32, "tile": 448}, "socketIdle": {"pal": 2, "size": 16, "tile": 398}, "socketLive": {"pal": 2, "size": 16, "tile": 428}, "treasure": {"pal": 1, "size": 16, "tile": 396}},
  scenes: {"factory": {"h": 28, "mx": 0, "my": 32, "pal": 2, "w": 32}, "logo": {"h": 6, "mx": 0, "my": 16, "pal": 3, "w": 32}},
  colors: {"CORAL": 121, "CYAN": 119, "DARK": 123, "GOLD": 118, "INK": 113, "MUTED": 116, "PANEL": 114, "PURPLE": 120, "STEEL": 122, "TRIM": 115, "WHITE": 117},
  gradients: {"sky":{"entry":0,"lines":[4162,4162,4162,4162,4162,4162,4162,4162,4162,4162,4162,5186,5186,5186,5186,5186,5186,5186,5186,5186,5186,5186,5186,5186,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,5187,6211,6211,6211,6211,6211,6211,6211,6211,6211,6211,6243,6243,6243,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,6244,7268,7268,7268,7268,7269,7269,7269,7269,7269,7269,7269,7269,7269,7269,7269,7269,7269,7269,7269,7269,7269,7269,7269,7269,7269,7269,7269,7269,7269,7269,7269,7269,7269,7269,7269,7269,7270,7270,7270,7270,7270,7270,7270,7270,7270,7270,7270,7302,7302,7302,7302,7302,7302,7302,7302,7302,7302,7302,7302,7302,7302,7302,7302,7302,7302,7302,7302,7303,7303,7303,7303,7303,7303,7303,7303,7303,7303,7303,7303,7303,7303,7303,7303,7303,7303,7303,7303,7303,7303,7303,7303,7303,7303,7303,7303,7303,7303,7303,7303,7304,7304,7304,7304,7304,7304],"y0":0}},
};
/** In scanline(y): set the CGRAM entry of a gradient from ART.gradients to its colour for line y (generated by art.py). */
function gradientLine(g, y) {
  const v = g.lines[y - g.y0];
  if (v !== undefined) color(g.entry, v & 31, (v >> 5) & 31, v >> 10);
}
// END ART

const SCREEN_W = 256, SCREEN_H = 224;
const COURSE_W = 768, COURSE_MAP_Y = 64;
const BODY_HALF = 7, BODY_H = 22;
const RUN_SPEED = 2.25, GROUND_ACCEL = 0.35, AIR_ACCEL = 0.22, BRAKE = 0.45;
const JUMP_SPEED = -4.7, HELD_GRAVITY = 0.22, GRAVITY = 0.30, FALL_LIMIT = 5.5;
const COYOTE_FRAMES = 6, BUFFER_FRAMES = 6, RESPAWN_FRAMES = 24;
const SOCKET_X_REACH = 20, SOCKET_Y_REACH = 12;
const PLUG_FRAMES = 12;
const SPAWN = { x: 32, y: 192 };
const BEACON = { x: 304, y: 192 };
const LIFT = { x: 424, w: 56, bottom: 192, top: 112, socketX: 452 };
const TREASURE = { x: 616, y: 62 };
const EXIT = { x: 744, y: 101 };

const deck = [
  { x: 0, y: 192, w: 184, h: 32 },
  { x: 224, y: 192, w: 168, h: 32 },
  { x: 520, y: 112, w: 128, h: 24 },
  { x: 688, y: 112, w: 80, h: 24 },
  { x: 592, y: 80, w: 48, h: 8, oneWay: true },
];

const SFX = { move: 0, confirm: 1, pause: 2, fall: 3, pickup: 5, clear: 6, jump: 7, plug: 8, checkpoint: 9 };
const SONG = { title: 0, stage: 1 };
const SFX_CH = [7, 6];
const SAVE_VERSION = 2, CLEAR_SLOT = 1, TREASURE_SLOT = 2, STAGE_BIT = 1;
const PAUSE_ITEMS = ['RESUME', 'RESTART STAGE', 'BACK TO TITLE'];
const BUTTONS = [UP, DOWN, LEFT, RIGHT, A, B, START];
const WALK = [ART.sprites.heroWalk1, ART.sprites.heroWalk2, ART.sprites.heroWalk3, ART.sprites.heroWalk4];
const C = ART.colors;

let skipTitle = false;
let state = 'title', paused = false, pauseSel = 0, clock = 0;
let input = 0, previousInput = 0, playing = -1, fxNext = 0;
let bit, lift, checkpoint, camera, deathTimer, falls;

function fx(n) {
  sfx(n, SFX_CH[fxNext]);
  fxNext ^= 1;
}

function play(song) {
  if (playing === song) return;
  playing = song;
  music(song);
}

function scene(layer, asset, opts) {
  bg(layer, { mx: asset.mx, my: asset.my, mw: asset.w, mh: asset.h, ...opts });
}

function buildTerrain() {
  const { deckTop, deckSide } = ART.tiles;
  const top = tile(deckTop, 1), side = tile(deckSide, 1);
  for (const { x, y, w, h } of deck) {
    for (let dy = 0; dy < h; dy += 8) {
      for (let dx = 0; dx < w; dx += 8) mset((x + dx) / 8, COURSE_MAP_Y + (y + dy) / 8, dy ? side : top);
    }
  }
}

function init() {
  if (dget(0) !== SAVE_VERSION) {
    for (let slot = 1; slot < 256; slot++) dset(slot, 0);
    dset(0, SAVE_VERSION);
  }
  buildTerrain();
  scene(2, ART.scenes.factory, { x: 0, y: 0, wrap: true, show: true });
  bg(1, { mx: 0, my: COURSE_MAP_Y, mw: COURSE_W / 8, mh: SCREEN_H / 8, x: 0, y: 0, wrap: false });
  scene(0, ART.scenes.logo, { x: 0, y: -48, wrap: false });
  if (skipTitle) startStage();
  else toTitle();
}

function toTitle() {
  state = 'title';
  paused = false;
  clock = 0;
  play(SONG.title);
}

function startStage() {
  lift = { x: LIFT.x, w: LIFT.w, y: LIFT.bottom, powered: false, direction: -1, wait: 0 };
  checkpoint = null;
  falls = 0;
  spawnBit(SPAWN);
  state = 'play';
  paused = false;
  clock = 0;
  play(SONG.stage);
}

function spawnBit({ x, y }) {
  bit = { x, y, vx: 0, vy: 0, support: deck.find(p => p.y === y && x >= p.x && x < p.x + p.w),
    coyote: COYOTE_FRAMES, jumpBuffer: 0, facingLeft: false, walk: 0,
    landUntil: 0, plugUntil: 0, cheerUntil: 0 };
  camera = clamp(x - SCREEN_W / 2, 0, COURSE_W - SCREEN_W);
  deathTimer = 0;
}

const held = b => (input & (1 << b)) !== 0;
const pressed = b => held(b) && !(previousInput & (1 << b));

function update() {
  previousInput = input;
  input = 0;
  for (const b of BUTTONS) if (btn(b)) input |= 1 << b;
  if (paused) {
    updatePause();
    return;
  }
  clock++;
  if (state === 'title' || state === 'clear') {
    if (pressed(A) || pressed(START)) {
      fx(SFX.confirm);
      startStage();
    } else if (state === 'clear' && pressed(B)) toTitle();
    return;
  }
  if (pressed(START)) {
    paused = true;
    pauseSel = 0;
    fx(SFX.pause);
    return;
  }
  updateStage();
}

function updatePause() {
  const direction = Number(pressed(DOWN)) - Number(pressed(UP));
  if (direction) {
    pauseSel = (pauseSel + direction + PAUSE_ITEMS.length) % PAUSE_ITEMS.length;
    fx(SFX.move);
  }
  if (pressed(B) || pressed(START)) {
    paused = false;
    fx(SFX.pause);
  } else if (pressed(A)) {
    fx(SFX.confirm);
    if (pauseSel === 1) startStage();
    else if (pauseSel === 2) toTitle();
    else paused = false;
  }
}

function advanceLift() {
  if (!lift.powered) return;
  if (lift.wait > 0) {
    lift.wait--;
    return;
  }
  lift.y += lift.direction;
  if (lift.y === LIFT.top || lift.y === LIFT.bottom) {
    lift.direction *= -1;
    lift.wait = lift.y === LIFT.top ? 60 : 45;
  }
}

function moveBit(previousLiftY) {
  const wasSupported = Boolean(bit.support);
  if (bit.support === lift) bit.y += lift.y - previousLiftY;
  if (pressed(A)) bit.jumpBuffer = BUFFER_FRAMES;
  if (bit.jumpBuffer > 0 && (wasSupported || bit.coyote > 0)) {
    bit.vy = JUMP_SPEED;
    bit.support = null;
    bit.coyote = 0;
    bit.jumpBuffer = 0;
    fx(SFX.jump);
  } else {
    bit.vy = Math.min(FALL_LIMIT, bit.vy + (held(A) && bit.vy < 0 ? HELD_GRAVITY : GRAVITY));
  }

  const direction = Number(held(RIGHT)) - Number(held(LEFT));
  if (direction) {
    bit.vx = clamp(bit.vx + direction * (wasSupported ? GROUND_ACCEL : AIR_ACCEL), -RUN_SPEED, RUN_SPEED);
    bit.facingLeft = direction < 0;
  } else {
    const brake = wasSupported ? BRAKE : AIR_ACCEL;
    bit.vx -= Math.sign(bit.vx) * Math.min(Math.abs(bit.vx), brake);
  }
  const fallSpeed = bit.vy;
  moveHorizontally();
  moveVertically(previousLiftY);
  if (!wasSupported && bit.support && fallSpeed > 2) bit.landUntil = clock + 6;

  if (bit.support) bit.coyote = COYOTE_FRAMES;
  else if (!wasSupported && bit.coyote > 0) bit.coyote--;
  if (bit.jumpBuffer > 0) bit.jumpBuffer--;
  bit.walk = bit.support && Math.abs(bit.vx) > 0.15 ? bit.walk + 1 : 0;
}

function moveHorizontally() {
  let x = clamp(bit.x + bit.vx, BODY_HALF, COURSE_W - BODY_HALF);
  for (const p of deck) {
    if (p.oneWay || bit.y <= p.y || bit.y - BODY_H >= p.y + p.h) continue;
    if (bit.vx > 0 && bit.x + BODY_HALF <= p.x) x = Math.min(x, p.x - BODY_HALF);
    if (bit.vx < 0 && bit.x - BODY_HALF >= p.x + p.w) x = Math.max(x, p.x + p.w + BODY_HALF);
  }
  if (x !== bit.x + bit.vx) bit.vx = 0;
  bit.x = x;
}

function overPlatform(p) {
  return bit.x + BODY_HALF > p.x && bit.x - BODY_HALF < p.x + p.w;
}

function moveVertically(previousLiftY) {
  let y = bit.y + bit.vy;
  let support = null;
  if (bit.vy >= 0) {
    for (const p of deck) {
      if (overPlatform(p) && bit.y <= p.y && y >= p.y) {
        y = p.y;
        support = p;
      }
    }
    // A rising lift can meet Bit between two frames, even when his own y hardly changed.
    if ((!support || lift.y < y) && overPlatform(lift) && bit.y <= Math.max(lift.y, previousLiftY) && y >= lift.y) {
      y = lift.y;
      support = lift;
    }
  } else {
    for (const p of deck) {
      const underside = p.y + p.h + BODY_H;
      if (!p.oneWay && overPlatform(p) && bit.y >= underside && y < underside) y = underside;
    }
  }
  if (support || y !== bit.y + bit.vy) bit.vy = 0;
  bit.y = y;
  bit.support = support;
}

function followBit() {
  camera = clamp(camera, bit.x - 160, bit.x - 96);
  camera = clamp(camera, 0, COURSE_W - SCREEN_W);
}

function interaction() {
  const socketY = lift.y - 10;
  const near = (x, y) => Math.abs(bit.x - x) <= SOCKET_X_REACH && Math.abs(bit.y - BODY_H / 2 - y) <= SOCKET_Y_REACH;
  if (!lift.powered && near(LIFT.socketX, socketY)) return 'lift';
  if (near(EXIT.x, EXIT.y)) return 'exit';
  return null;
}

const hasTreasure = () => (dget(TREASURE_SLOT) & STAGE_BIT) !== 0;
const stageCleared = () => (dget(CLEAR_SLOT) & STAGE_BIT) !== 0;

function updateStage() {
  if (deathTimer > 0) {
    if (--deathTimer === 0) {
      if (checkpoint) Object.assign(lift, checkpoint.lift);
      else Object.assign(lift, { y: LIFT.bottom, powered: false, direction: -1, wait: 0 });
      spawnBit(checkpoint ? BEACON : SPAWN);
    }
    return;
  }

  const previousLiftY = lift.y;
  advanceLift();
  moveBit(previousLiftY);
  followBit();

  if (bit.y - BODY_H >= SCREEN_H + 8) {
    deathTimer = RESPAWN_FRAMES;
    falls++;
    fx(SFX.fall);
    return;
  }
  if (!checkpoint && bit.support && bit.y === BEACON.y && Math.abs(bit.x - BEACON.x) < 12) {
    checkpoint = { lift: { ...lift } };
    fx(SFX.checkpoint);
  }
  if (!hasTreasure() && Math.abs(bit.x - TREASURE.x) < 14 && Math.abs(bit.y - BODY_H / 2 - TREASURE.y) < 15) {
    dset(TREASURE_SLOT, dget(TREASURE_SLOT) | STAGE_BIT);
    bit.cheerUntil = clock + 18;
    fx(SFX.pickup);
  }
  if (!pressed(B)) return;
  const socket = interaction();
  if (socket === 'lift') {
    lift.powered = true;
    bit.plugUntil = clock + PLUG_FRAMES;
    fx(SFX.plug);
  } else if (socket === 'exit') {
    dset(CLEAR_SLOT, dget(CLEAR_SLOT) | STAGE_BIT);
    state = 'clear';
    fx(SFX.clear);
  }
}

function draw() {
  cls();
  const title = state === 'title';
  bg(0, { show: title });
  bg(1, { show: !title });
  const scroll = title ? Math.floor(clock / 4) : Math.floor(camera);
  bgscroll(2, Math.floor(scroll / 3), 0);
  if (title) drawTitle();
  else {
    bgscroll(1, scroll, 0);
    drawStage(scroll);
    if (paused) drawPause();
    else if (state === 'clear') drawClear();
  }
}

function drawTitle() {
  centered('CONTROLLER FOUNDRY', 113, C.MUTED);
  panel(57, 155, 142, 31);
  centered(stageCleared() ? 'A  REPLAY' : 'A  PLAY', 166, clock % 80 < 60 ? C.WHITE : C.MUTED);
}

function drawStage(scroll) {
  const liftX = lift.x - scroll;
  const prompt = interaction();
  clip(0, 16, SCREEN_W, SCREEN_H - 16);
  for (const x of [liftX + 3, liftX + LIFT.w - 5]) {
    rectfill(x, LIFT.top, 2, LIFT.bottom - LIFT.top + 8, C.TRIM);
  }
  rectfill(liftX, lift.y, LIFT.w, 8, C.INK);
  rectfill(liftX + 1, lift.y, LIFT.w - 2, 2, lift.powered ? C.CYAN : C.CORAL);
  rectfill(liftX + 3, lift.y + 4, LIFT.w - 6, 2, C.STEEL);
  drawSocket(LIFT.socketX - scroll, lift.y - 10, lift.powered ? ART.sprites.socketLive : ART.sprites.socketIdle, prompt === 'lift' ? 'B PLUG' : '');
  drawSocket(EXIT.x - scroll, EXIT.y, ART.sprites.socketLive, prompt === 'exit' ? 'B EXIT' : '');
  if (clock < bit.plugUntil) drawPlugSparks(LIFT.socketX - scroll, lift.y - 10);
  if (scroll < 140) {
    rectfill(77 - scroll, 140, 62, 14, C.PANEL);
    print('A JUMP', 84 - scroll, 144, C.MUTED);
  }
  const beaconX = BEACON.x - scroll;
  rectfill(beaconX - 1, BEACON.y - 30, 3, 30, C.TRIM);
  rectfill(beaconX + 2, BEACON.y - 29, 11, 7, checkpoint ? C.CYAN : C.PURPLE);
  rectfill(beaconX + 2, BEACON.y - 24, 11, 2, checkpoint ? C.STEEL : C.TRIM);

  if (!hasTreasure()) {
    const bob = Math.floor(clock / 12) % 4;
    drawSprite(ART.sprites.treasure, TREASURE.x - scroll - 8, TREASURE.y - 8 + (bob === 3 ? 1 : bob));
  }
  if (!deathTimer) {
    drawSprite(bitSprite(), Math.floor(bit.x) - scroll - 16, Math.floor(bit.y) - 31, bit.facingLeft);
  }
  clip();
  rectfill(0, 0, SCREEN_W, 15, C.PANEL);
  rectfill(0, 15, SCREEN_W, 1, C.TRIM);
  print('1-1 FOUNDRY', 5, 4, C.WHITE);
  print(hasTreasure() ? 'TREASURE 1/1' : 'TREASURE 0/1', 154, 4, hasTreasure() ? C.GOLD : C.MUTED);
  if (deathTimer && !paused) centered('REBOOTING', 70, C.MUTED);
}

function bitSprite() {
  const sprites = ART.sprites;
  if (state === 'clear' || clock < bit.cheerUntil) return sprites.heroCheer;
  if (clock < bit.plugUntil) return sprites.heroPlug;
  if (!bit.support) return bit.vy < 0 ? sprites.heroJump : sprites.heroFall;
  if (clock < bit.landUntil) return sprites.heroLand;
  if (bit.walk) return WALK[Math.floor(bit.walk / 5) % WALK.length];
  return clock % 150 >= 145 ? sprites.heroBlink : sprites.heroIdle;
}

function drawPlugSparks(x, y) {
  const spread = Math.floor((PLUG_FRAMES + clock - bit.plugUntil) / 3);
  line(x - 9 - spread, y - 8, x - 12 - spread, y - 11, C.CYAN);
  line(x + 13 + spread, y - 5, x + 16 + spread, y - 7, C.CYAN);
  rectfill(x + 9, y - 13 - spread, 1, 2, C.GOLD);
}

function drawSocket(x, y, asset, prompt) {
  drawSprite(asset, x - 8, y - 8, false, 2);
  if (!prompt || paused || deathTimer || state !== 'play') return;
  const width = prompt.length * 8;
  const left = clamp(x - width / 2, 3, SCREEN_W - width - 3);
  rectfill(left - 2, y - 32, width + 4, 13, C.INK);
  print(prompt, left, y - 30, C.WHITE);
}

function drawSprite(asset, x, y, flip = false, prio = 3) {
  if (x <= -asset.size || x >= SCREEN_W || y <= -asset.size || y >= SCREEN_H) return;
  spr(asset.tile, x, y, { size: asset.size, pal: asset.pal, prio, fx: flip });
}

function drawPause() {
  panel(49, 70, 158, 83);
  centered('PAUSED', 80, C.GOLD);
  for (let i = 0; i < PAUSE_ITEMS.length; i++) {
    print(i === pauseSel ? '>' : ' ', 60, 99 + i * 14, C.CYAN);
    print(PAUSE_ITEMS[i], 76, 99 + i * 14, i === pauseSel ? C.WHITE : C.MUTED);
  }
}

function drawClear() {
  panel(36, 68, 184, 87);
  centered('STAGE CLEAR', 79, C.GOLD);
  centered(hasTreasure() ? 'TREASURE FOUND' : 'TREASURE MISSING', 99, C.MUTED);
  centered('A REPLAY   B TITLE', 129, C.WHITE);
}

function panel(x, y, w, h) {
  rectfill(x + 3, y + 3, w, h, C.INK);
  rectfill(x, y, w, h, C.PANEL);
  rect(x, y, w, h, C.TRIM);
}

function centered(text, y, colorIndex) {
  print(text, 128 - text.length * 4, y, colorIndex);
}

function scanline(y) {
  gradientLine(ART.gradients.sky, y);
}
